data ReadyEnded = ReadyEnded
  { announced :: [Integer]
  , faults :: Object
  , reason :: Text
  }
  deriving stock (Eq, Show)

instance Contract ReadyEnded where
  contract =
    recordWith "ReadyEnded" positional $
      ReadyEnded
        <$> field "announced" (.announced) (list integer)
        <*> field "faults" (.faults) object
        <*> field "reason" (.reason) text
    where
      positional = \case
        [(_, v0), (_, v1), (_, v2)] ->
          Just $
            ReadyEnded
              <$> member "announced" (list integer) v0
              <*> member "faults" object v1
              <*> member "reason" text v2
        _ -> Nothing

